using System;using System.IO;using System.Linq;using System.Reflection;using SargasPC;
class SecurityTests {
 static int n;static void Check(bool x){if(!x)throw new Exception("Security check "+n);n++;}
 static void Reject(Action a){bool failed=false;try{a();}catch(IOException){failed=true;}Check(failed);}
 static string Run(Core c,Func<string,CommandOutput> f){try{return (string)typeof(Core).GetMethod("RunDetectionControl",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{f});}catch(TargetInvocationException e){throw e.InnerException;}}
 static string Readiness(Core c,Func<string,CommandOutput> f){try{return (string)typeof(Core).GetMethod("RunLocalEngineReadiness",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{f});}catch(TargetInvocationException e){throw e.InnerException;}}
 static CommandOutput Output(bool found){return new CommandOutput{ExitCode=found?1:0,Output=(found?"control: Win.Test.EICAR_HDB-1 FOUND\n":"")+"Scanned files: 1\n",Error=""};}
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"sargon-security-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
  string db=Path.Combine(root,"db");Directory.CreateDirectory(db);Reject(()=>EngineSafety.ValidateDatabaseFiles(db));File.WriteAllBytes(Path.Combine(db,"main.cvd"),new byte[512]);Reject(()=>EngineSafety.ValidateDatabaseFiles(db));File.WriteAllBytes(Path.Combine(db,"daily.cld"),new byte[511]);Reject(()=>EngineSafety.ValidateDatabaseFiles(db));File.WriteAllBytes(Path.Combine(db,"daily.cld"),new byte[512]);EngineSafety.ValidateDatabaseFiles(db);Check(true);
  long now=DateTime.UtcNow.Ticks;Check(EngineSafety.ControlStatus(0,now).Contains("nepatvirtinta"));Check(EngineSafety.ControlStatus(now+1,now).Contains("nepatvirtinta"));Check(EngineSafety.ControlStatus(now-TimeSpan.FromHours(25).Ticks,now).Contains("senesnė"));Check(EngineSafety.ControlStatus(now,now).Contains("praėjo"));
  var clean=LocalEngine.Parse(Output(false));var found=LocalEngine.Parse(Output(true));Check(EngineSafety.DetectionMatches(clean,found));Check(!EngineSafety.DetectionMatches(found,found));Check(!EngineSafety.DetectionMatches(clean,clean));found.Signatures=new[]{"Other.Signature"};Check(!EngineSafety.DetectionMatches(clean,found));found=LocalEngine.Parse(Output(true));found.Incomplete=true;Check(!EngineSafety.DetectionMatches(clean,found));Check(!EngineSafety.DetectionMatches(null,found));
  Check(EngineSafety.NeutralReadinessPassed(clean));Check(!EngineSafety.NeutralReadinessPassed(found));var zero=LocalEngine.Parse(new CommandOutput{ExitCode=0,Output="Scanned files: 0\n",Error=""});Check(!EngineSafety.NeutralReadinessPassed(zero));
  var c=new Core(Path.Combine(root,"profile"));int calls=0;string report=Run(c,p=>{calls++;byte[] b=File.ReadAllBytes(p);if(calls==2){Check(b.Length==68);Check(Data.Marker(b));}return Output(calls==2);});Check(calls==2);Check(c.Config.EngineDetectionAt>0);Check(c.TestFindings==1&&c.EngineFindings==0);Check(report.Contains("pašalinti"));Check(!Directory.GetDirectories(c.Root,"detection-control-*").Any());Check(new Core(c.Root).Config.EngineDetectionAt>0);
  c.Reset();calls=0;Reject(()=>Run(c,p=>{calls++;return Output(false);}));Check(c.Config.EngineDetectionAt==0);Check(!Directory.GetDirectories(c.Root,"detection-control-*").Any());
  c.Config.EngineDetectionAt=now;c.SaveSettings();calls=0;Reject(()=>Run(c,p=>{calls++;if(calls==2){File.Delete(p);}return Output(calls==2);}));Check(c.Config.EngineDetectionAt==0);Check(!Directory.GetDirectories(c.Root,"detection-control-*").Any());
  c.Reset();calls=0;bool cancelled=false;try{Run(c,p=>{c.Cancelled=true;return Output(false);});}catch(OperationCanceledException){cancelled=true;}Check(cancelled);Check(c.Config.EngineDetectionAt==0);Check(!Directory.GetDirectories(c.Root,"detection-control-*").Any());
  c.Reset();string readiness=Readiness(c,p=>{Check(File.ReadAllText(p)=="SARGON neutral ClamAV database runtime readiness control.");return Output(false);});Check(readiness.Contains("įkėlė dabar esančias bazes"));Check(!Directory.GetDirectories(c.Root,"engine-readiness-*").Any());
  c.Reset();Reject(()=>Readiness(c,p=>Output(true)));Check(!Directory.GetDirectories(c.Root,"engine-readiness-*").Any());
  c.Reset();Reject(()=>Readiness(c,p=>new CommandOutput{ExitCode=0,Output="Scanned files: 0\n",Error=""}));Check(!Directory.GetDirectories(c.Root,"engine-readiness-*").Any());
  c.Reset();Reject(()=>Readiness(c,p=>{File.WriteAllText(p,"changed while scanning");return Output(false);}));Check(!Directory.GetDirectories(c.Root,"engine-readiness-*").Any());
  Console.WriteLine("PASS: "+n+" security/readiness checks (simulated scanner responses; native Windows ClamAV and efficacy not claimed).");
 }finally{Directory.Delete(root,true);}}
}
